<script setup>
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue';

const props = defineProps({open:Boolean,unlock:Boolean,capture:Boolean,schedule:Boolean,requireSecrets:Boolean,strengthFor:{type:Function,required:true}});
const emit = defineEmits(['confirm','cancel']);
const password=ref(''),confirmation=ref(''),field=ref(null),includeSecrets=ref(props.requireSecrets);
const strength=computed(()=>props.strengthFor(password.value));
const valid=computed(()=>props.capture&&!includeSecrets.value || (props.unlock?password.value.length>0:strength.value.acceptable&&password.value===confirmation.value));
function clear(){password.value='';confirmation.value='';}
watch(()=>props.open,async()=>{clear();await nextTick();field.value?.focus();},{immediate:true});
watch(includeSecrets,async()=>{clear();await nextTick();field.value?.focus();});
function cancel(){clear();emit('cancel');}
function confirm(){if(!valid.value)return;const value=props.capture?{includeSecrets:includeSecrets.value,password:includeSecrets.value?password.value:''}:password.value;clear();emit('confirm',value);}
function keys(event){if(event.key==='Escape'){event.stopPropagation();cancel();}if(event.key==='Tab'){const fields=[...event.currentTarget.querySelectorAll('input:not(:disabled),button:not(:disabled)')];const index=fields.indexOf(document.activeElement);if(event.shiftKey&&index===0){event.preventDefault();fields.at(-1)?.focus();}else if(!event.shiftKey&&index===fields.length-1){event.preventDefault();fields[0]?.focus();}}}
onBeforeUnmount(clear);
</script>
<template><div v-if="open" class="backup-overlay rcui-surface" @keydown.stop="keys"><form class="backup-dialog" role="dialog" aria-modal="true" aria-labelledby="backup-title" @submit.prevent="confirm"><h2 id="backup-title">{{capture?'Snapshot Options':unlock?'Unlock Backup':'Protect Entire Backup'}}</h2><label v-if="capture" class="choice"><input ref="field" v-model="includeSecrets" type="checkbox" :disabled="requireSecrets">Include Secrets</label><p>{{capture?'Configuration is always included. Including Secrets encrypts the entire ZIP and requires a password.':unlock?'Enter the password used to encrypt this ZIP.':'Keep this password separately; it cannot be recovered.'}}</p><p v-if="schedule && includeSecrets">The schedule password is saved in a backend Secret for automatic snapshots and protected ZIP recovery.</p><template v-if="!capture||includeSecrets"><label>Password<input v-model="password" type="password" :autocomplete="unlock?'current-password':'new-password'" required></label><template v-if="!unlock"><meter min="0" max="4" :value="strength.score" aria-label="Password strength"/><p role="status">{{strength.label}} · Use 14+ varied characters or a long passphrase.</p><label>Confirm Password<input v-model="confirmation" type="password" autocomplete="new-password" required></label><p v-if="confirmation&&confirmation!==password" role="alert">Passwords do not match.</p></template></template><div class="backup-actions"><button type="button" @click="cancel">Cancel</button><button type="submit" :disabled="!valid">{{schedule?'Save Schedule':capture?'Create Snapshot':unlock?'Unlock':'Use Password'}}</button></div></form></div></template>
<style>.backup-overlay{position:fixed;inset:0;z-index:150;background:#0009;display:grid;place-items:center;padding:20px}.backup-dialog{width:min(480px,100%);max-height:90dvh;overflow:auto;background:var(--box-bg,#171c22);color:var(--body-text,snow);border:1px solid var(--border,#38404b);padding:24px;border-radius:6px;font:14px Lato,Arial,sans-serif}.backup-dialog label{display:flex;flex-direction:column;gap:8px;margin-top:16px}.backup-dialog input{height:40px;background:var(--input-bg,#25282f);color:inherit;border:1px solid var(--border,#38404b);padding:10px}.backup-dialog .choice{flex-direction:row;align-items:center}.backup-dialog input[type=checkbox]{height:auto}.backup-dialog meter{width:100%;margin-top:10px}.backup-dialog p{line-height:1.5}.backup-actions{display:flex;gap:12px;justify-content:flex-start;margin-top:20px}.backup-actions button{min-height:40px;background:var(--primary,#2f68df);color:white;padding:10px 14px;border:0;border-radius:4px;font:inherit}.backup-actions button:disabled{opacity:.5}.backup-dialog :focus-visible{outline:2px solid var(--link,#9bbffd);outline-offset:2px}</style>
